{
  "headline": "FDA's records trace our supply to a plant classified OAI 23 days before the shortage posting",
  "headline_cites": ["E8"],
  "sentences": [
    {
      "text": "FDA first posted the carboplatin shortage on 2023-04-28 and it remains current as of 2026-10-21.",
      "cites": ["E31", "E9"]
    },
    {
      "text": "The Accord Healthcare product (NDC 16729-295-12) on the shortage list is manufactured by Intas Pharmaceuticals Limited (FEI 3004011473).",
      "cites": ["E20", "E21"]
    },
    {
      "text": "FDA inspection 1191818 of that Intas plant ended 2022-12-02 and was classified OAI; the classification letter is dated 2023-04-05, 23 days before the shortage posting.",
      "cites": ["E16", "E8"]
    },
    {
      "text": "An import alert (66-40) for Intas was published 2023-06-01 and a Warning Letter was issued 2023-07-28, both after the shortage posting.",
      "cites": ["E18", "E17"]
    },
    {
      "text": "Our Corvale East inventory includes Teva product (NDC 00703423901) made by Pharmachemie BV and Apotex product (NDC 60505628201) made by Teyro Labs, which had a VAI inspection ending 2025-11-12.",
      "cites": ["E1", "E2", "E9", "E11", "E10"]
    },
    {
      "text": "P&T has approved interchange between the Teva and Apotex presentations (same product, alternate manufacturer) and between the Accord and Teva presentations (same molecule, alternate concentration or vial size).",
      "cites": ["E32", "E33"]
    }
  ]
}
